import { Component, computed, input, output } from '@angular/core';
import { RequisitoTramite, RequisitoDocumento } from '../../models/solicitud.model';
import { ModalidadValue } from '../../models/tramite.model';
import { DocumentUploaderComponent } from '../document-uploader/document-uploader';

const MODALIDAD_LABEL: Record<ModalidadValue, string> = {
  en_linea: 'En línea',
  presencial: 'Presencial',
};

const NIVEL_LABEL: Record<string, string> = {
  estatal: 'Estatal',
  municipal: 'Municipal',
  federal: 'Federal',
};

export interface DocumentoTramiteState {
  file: File | null;
  id: number | null;
}

@Component({
  selector: 'app-seccion-tramite-documentos',
  imports: [DocumentUploaderComponent],
  templateUrl: './seccion-tramite-documentos.component.html',
})
export class SeccionTramiteDocumentosComponent {
  tramite = input.required<RequisitoTramite>();
  documentosMap = input.required<Record<string, DocumentoTramiteState>>();

  readonly canalLabels = computed(() => {
    const mod = this.tramite().modalidad;
    if (!mod || mod.length === 0) return [];
    return mod.map(m => MODALIDAD_LABEL[m] ?? m);
  });

  readonly nivelLabel = computed(() => {
    const nivel = this.tramite().nivelGobierno;
    if (!nivel) return null;
    return NIVEL_LABEL[nivel] ?? nivel;
  });

  fileChange = output<{ clave: string; file: File | null }>();
  idChange = output<{ clave: string; id: number | null }>();
  view = output<{ file: File | null; title: string; documentId?: number | null }>();

  getClave(requisito: RequisitoDocumento): string {
    return `tramite_${this.tramite().id}_doc_${requisito.id}`;
  }

  getFile(clave: string): File | null {
    return this.documentosMap()[clave]?.file ?? null;
  }

  getDocumentId(clave: string): number | null {
    return this.documentosMap()[clave]?.id ?? null;
  }

  onFileChange(clave: string, file: File | null) {
    this.fileChange.emit({ clave, file });
  }

  onIdChange(clave: string, id: number | null) {
    this.idChange.emit({ clave, id });
  }

  onViewFile(file: File | null, title: string, documentId?: number | null) {
    this.view.emit({ file, title, documentId });
  }
}
