import { Component, DestroyRef, inject, signal, computed, OnInit } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { Router } from '@angular/router';
import { forkJoin } from 'rxjs';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators, ValidatorFn, AbstractControl, ValidationErrors } from '@angular/forms';
import { DomSanitizer, SafeResourceUrl } from '@angular/platform-browser';
import { DocumentUploaderComponent } from '../../../../shared/components/document-uploader/document-uploader';
import { SeccionTramiteDocumentosComponent, DocumentoTramiteState } from '../../../../shared/components/seccion-tramite-documentos/seccion-tramite-documentos.component';
import { SolicitudService, SolicitudFormValue } from '../../../../shared/services/solicitud.service';
import { DocumentoService, TipoDocumento } from '../../../../services/documento.service';
import { Municipio } from '../../../../shared/models/municipio.model';
import { RequisitoTramite } from '../../../../shared/models/solicitud.model';
import { UppercaseDirective } from '../../../../shared/directives/uppercase.directive';
import { MascaraNumerosDirective } from '../../../../shared/directives/mascara-numeros.directive';
import { environment } from '../../../../../environments/environment';
import { FirmaEfirmaModalComponent, DocumentoAFirmar, ResultadoFirma } from '../../../../shared/components/firma-efirma-modal/firma-efirma-modal.component';
import { SignMetadata } from '../../../../shared/utils/pdf-sign.util';
import { extractErrorMessage } from '../../../../shared/utils/error-utils';

export type PersonalidadJuridica = 'fisica' | 'moral';

const STORAGE_KEY = 'firma_flow_v1';
const FLOW_TTL = 24 * 60 * 60 * 1000;

interface SavedFlow {
  flowId: string;
  savedAt: number;
  personalidadJuridica: PersonalidadJuridica;
  nombreProyecto: string;
  municipioId?: number | null;
  allowedClaves: string[];
  formValues: Record<string, unknown>;
  docs: { clave: string; id: number; nombre: string }[];
}

export function emailMismatchValidator(): ValidatorFn {
  return (group: AbstractControl): ValidationErrors | null => {
    const email = group.get('correoElectronico');
    const confirm = group.get('confirmarCorreo');
    if (!email || !confirm) return null;

    const emailValue = email.value?.trim() ?? '';
    const confirmValue = confirm.value?.trim() ?? '';
    if (emailValue && confirmValue && emailValue !== confirmValue) {
      return { emailMismatch: true };
    }
    return null;
  };
}

export function montoValidator(): ValidatorFn {
  return (group: AbstractControl): ValidationErrors | null => {
    const sector = group.get('sectorEstrategico')?.value;
    const monto = group.get('montoInversion')?.value;
    if (sector === false || sector === 'false' || sector === null) {
      if (monto === null || monto === undefined || monto === '') {
        return { montoRequerido: true };
      }
      const cleanMonto = typeof monto === 'string' ? monto.replace(/,/g, '') : monto;
      if (Number(cleanMonto) < 2000000000) {
        return { montoMinimo: true };
      }
    }
    return null;
  };
}

@Component({
  selector: 'app-nueva-solicitud',
  imports: [
    ReactiveFormsModule,
    DocumentUploaderComponent,
    SeccionTramiteDocumentosComponent,
    FirmaEfirmaModalComponent,
    UppercaseDirective,
    MascaraNumerosDirective,
  ],
  templateUrl: './nueva.component.html',
  styleUrl: './nueva.component.scss',
})
export class NuevaComponent implements OnInit {
  private fb = inject(FormBuilder);
  private router = inject(Router);
  private sanitizer = inject(DomSanitizer);
  private solicitudService = inject(SolicitudService);
  private documentoService = inject(DocumentoService);
  private readonly destroyRef = inject(DestroyRef);

  steps = ['Datos del inversionista', 'Documentación del proyecto'];
  currentStep = signal(0);
  personalidadJuridica = signal<PersonalidadJuridica>('fisica');
  isSubmitting = signal(false);
  submitSuccess = signal(false);
  submitFolio = signal('');
  submitId = signal<number | null>(null);
  submitError = signal<string | null>(null);
  previewUrl = signal<SafeResourceUrl | null>(null);
  previewTitle = signal<string>('');
  showPreviewModal = signal<boolean>(false);
  nombreProyecto = signal('');
  nombreProyectoTouched = signal(false);
  municipioId = signal<number | null>(null);
  municipioTouched = signal(false);
  municipios = signal<Municipio[]>([]);
  showFirmaModal = signal(false);
  isSigning = signal(false);
  signError = signal<string | null>(null);
  docsParaFirmar = signal<DocumentoAFirmar[]>([]);
  signedClaves = signal<string[]>([]);
  firmaMetadata = signal<SignMetadata | undefined>(undefined);
  showResumeDialog = signal(false);
  resumeHint = signal(false);
  resumeFlow = signal<SavedFlow | null>(null);

  tiposDocumento = signal<TipoDocumento[]>([]);
  documentosMap = signal<Record<string, { file: File | null; id: number | null }>>({});
  etapaSeleccionada = signal<string | null>(null);
  tramitesRequisitos = signal<RequisitoTramite[]>([]);
  tramitesMap = signal<Record<string, DocumentoTramiteState>>({});
  isLoadingTramites = signal(false);

  fisicaForm: FormGroup = this.fb.group({
    nombreCompleto: ['', Validators.required],
    rfc: ['', [Validators.required, Validators.pattern(/^[A-ZÑ&]{3,4}\d{6}[A-Z0-9]{3}$/)]],
    correoElectronico: ['', [Validators.required, Validators.email]],
    confirmarCorreo: ['', [Validators.required, Validators.email]],
    tieneRepresentanteLegal: [false],
    etapa: ['', Validators.required],
    sectorEstrategico: [false],
    montoInversion: [null]
  }, { validators: [emailMismatchValidator(), montoValidator()] });

  moralForm: FormGroup = this.fb.group({
    denominacionRazonSocial: ['', Validators.required],
    rfc: ['', [Validators.required, Validators.pattern(/^[A-ZÑ&]{3,4}\d{6}[A-Z0-9]{3}$/)]],
    correoElectronico: ['', [Validators.required, Validators.email]],
    confirmarCorreo: ['', [Validators.required, Validators.email]],
    numeroFolio: ['', Validators.required],
    fechaOtorgamiento: ['', Validators.required],
    nombreRepresentante: ['', Validators.required],
    primerApellidoRepresentante: ['', Validators.required],
    segundoApellidoRepresentante: [''],
    etapa: ['', Validators.required],
    sectorEstrategico: [false],
    montoInversion: [null]
  }, { validators: [emailMismatchValidator(), montoValidator()] });

  get activeForm(): FormGroup {
    return this.isMoral() ? this.moralForm : this.fisicaForm;
  }

  isMoral = computed(() => this.personalidadJuridica() === 'moral');

  documentosInversionista = computed(() => {
    const activePersonality = this.personalidadJuridica();
    const etapa = this.etapaSeleccionada();
    return this.tiposDocumento().filter(tipo => 
      tipo.clave !== 'solicitud_firmada' &&
      tipo.tab === 'inversionista' && 
      (tipo.personalidad === null || tipo.personalidad === activePersonality) &&
      (!tipo.etapa || tipo.etapa === etapa || etapa === 'ambas')
    );
  });

  stepOneValid(): boolean {
    if (!this.activeForm.valid) return false;
    const requiredDocs = this.documentosInversionista().filter(tipo => tipo.requerido);
    const docs = this.documentosMap();
    return requiredDocs.every(tipo => docs[tipo.clave]?.id !== undefined && docs[tipo.clave]?.id !== null);
  }

  stepTwoValid(): boolean {
    if (!this.nombreProyecto().trim()) return false;
    if (this.municipioId() === null || this.municipioId() === undefined) return false;
    const tramites = this.tramitesRequisitos();
    const tramitesDocs = this.tramitesMap();
    return tramites.every(tramite =>
      tramite.requisitos
        .filter(r => r.es_obligatorio)
        .every(r => {
          const clave = `tramite_${tramite.id}_doc_${r.id}`;
          return tramitesDocs[clave]?.id !== undefined && tramitesDocs[clave]?.id !== null;
        })
    );
  }

  onMunicipioChange(value: string) {
    const val = value ? parseInt(value, 10) : null;
    this.municipioId.set(val);
    this.municipioTouched.set(true);
    this.loadTramitesRequisitos();
  }

  ngOnInit() {
    this.solicitudService.getMunicipios().pipe(
      takeUntilDestroyed(this.destroyRef),
    ).subscribe({
      next: (municipios) => this.municipios.set(municipios),
      error: () => this.submitError.set('Error al cargar los municipios.'),
    });

    this.documentoService.getTiposDocumento().pipe(
      takeUntilDestroyed(this.destroyRef),
    ).subscribe({
      next: (tipos) => {
        this.tiposDocumento.set(tipos);
        this.checkResumeFlow();
      },
      error: () => {
        this.submitError.set('Error al cargar la configuración de los documentos.');
      }
    });
  }

  private checkResumeFlow(): void {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (!stored) return;

    try {
      const flow: SavedFlow = JSON.parse(stored);
      if (Date.now() - flow.savedAt > FLOW_TTL) {
        localStorage.removeItem(STORAGE_KEY);
        return;
      }
      this.resumeFlow.set(flow);
      this.showResumeDialog.set(true);
    } catch {
      localStorage.removeItem(STORAGE_KEY);
    }
  }

  onPersonalidadChange(tipo: PersonalidadJuridica) {
    this.personalidadJuridica.set(tipo);
  }

  onEtapaChange(etapa: string) {
    this.etapaSeleccionada.set(etapa);
    this.fisicaForm.get('etapa')?.setValue(etapa);
    this.moralForm.get('etapa')?.setValue(etapa);
    this.loadTramitesRequisitos();
  }

  onSectorEstrategicoChange(esEstrategico: boolean) {
    this.fisicaForm.get('sectorEstrategico')?.setValue(esEstrategico);
    this.moralForm.get('sectorEstrategico')?.setValue(esEstrategico);
    this.fisicaForm.get('montoInversion')?.updateValueAndValidity();
    this.moralForm.get('montoInversion')?.updateValueAndValidity();
  }

  private loadTramitesRequisitos() {
    const etapa = this.etapaSeleccionada();
    const municipioId = this.municipioId();
    if (!etapa || !municipioId) {
      this.tramitesRequisitos.set([]);
      this.tramitesMap.set({});
      return;
    }
    this.isLoadingTramites.set(true);
    this.solicitudService.getRequisitos(etapa, municipioId).pipe(
      takeUntilDestroyed(this.destroyRef),
    ).subscribe({
      next: (tramites) => {
        this.tramitesRequisitos.set(tramites);
        this.isLoadingTramites.set(false);
      },
      error: () => {
        this.tramitesRequisitos.set([]);
        this.isLoadingTramites.set(false);
      },
    });
  }

  onTramiteFileChange(event: { clave: string; file: File | null }) {
    this.tramitesMap.update(map => ({
      ...map,
      [event.clave]: {
        file: event.file,
        id: map[event.clave]?.id ?? null,
      },
    }));
  }

  onTramiteIdChange(event: { clave: string; id: number | null }) {
    this.tramitesMap.update(map => ({
      ...map,
      [event.clave]: {
        file: map[event.clave]?.file ?? null,
        id: event.id,
      },
    }));
  }

  onTramiteViewFile(event: { file: File | null; title: string; documentId?: number | null }) {
    this.viewFile(event.file, event.title, event.documentId);
  }

  continuarFirma(): void {
    const flow = this.resumeFlow();
    if (!flow) return;

    this.personalidadJuridica.set(flow.personalidadJuridica);
    this.nombreProyecto.set(flow.nombreProyecto);
    this.municipioId.set(flow.municipioId ?? null);
    
    const etapa = flow.formValues['etapa'] as string;
    if (etapa) {
      this.etapaSeleccionada.set(etapa);
    }

    this.activeForm.patchValue(flow.formValues);

    const docsMap: Record<string, { file: null; id: number | null }> = {};
    const trMap: Record<string, DocumentoTramiteState> = {};
    for (const doc of flow.docs) {
      if (doc.clave.startsWith('tramite_')) {
        trMap[doc.clave] = { file: null, id: doc.id };
      } else {
        docsMap[doc.clave] = { file: null, id: doc.id };
      }
    }
    this.documentosMap.set(docsMap);
    this.tramitesMap.set(trMap);

    this.showResumeDialog.set(false);
    this.resumeHint.set(true);

    const observables = flow.docs.map(doc =>
      this.documentoService.getDocumentoEstado(doc.id),
    );

    forkJoin(observables).pipe(
      takeUntilDestroyed(this.destroyRef),
    ).subscribe(results => {
      const signedNombres: string[] = [];
      results.forEach((result, index) => {
        if (result.firmaSerial) {
          signedNombres.push(flow.docs[index].clave);
        }
      });
      this.signedClaves.set(signedNombres);
      this.saveFlowToStorage();
    });
  }

  empezarDeNuevo(): void {
    localStorage.removeItem(STORAGE_KEY);
    this.showResumeDialog.set(false);
    this.signedClaves.set([]);
    this.resumeFlow.set(null);
    this.resumeHint.set(false);
  }

  private saveFlowToStorage(): void {
    const docsMap = this.documentosMap();
    const storedFlow = this.resumeFlow();
    const docs = Object.entries(docsMap)
      .filter(([, entry]) => entry.id !== null)
      .map(([clave, entry]) => ({
        clave,
        id: entry.id!,
        nombre: entry.file?.name ?? storedFlow?.docs.find(d => d.clave === clave)?.nombre ?? '',
      }));

    const tramitesDocsMap = this.tramitesMap();
    Object.entries(tramitesDocsMap)
      .filter(([, entry]) => entry.id !== null)
      .forEach(([clave, entry]) => {
        docs.push({
          clave,
          id: entry.id!,
          nombre: entry.file?.name ?? storedFlow?.docs.find(d => d.clave === clave)?.nombre ?? '',
        });
      });

    const allowedClaves = [
      ...this.documentosInversionista().map(d => d.clave),
    ];

    const flow: SavedFlow = {
      flowId: crypto.randomUUID(),
      savedAt: Date.now(),
      personalidadJuridica: this.personalidadJuridica(),
      nombreProyecto: this.nombreProyecto(),
      municipioId: this.municipioId(),
      allowedClaves,
      formValues: { ...this.activeForm.value },
      docs,
    };

    localStorage.setItem(STORAGE_KEY, JSON.stringify(flow));
  }

  /**
   * Indica si el File tiene contenido de bytes real (no es un placeholder de restauración).
   *
   * Gotcha: DocumentUploaderComponent.restoreFromDocumentId() restaura documentos subidos
   * creando un File de 0 bytes (`new File([], nombre)`) pero sobreescribe la propiedad `.size`
   * con el tamaño original del archivo vía Object.defineProperty. Por eso `file.size` es
   * engañoso (reporta el tamaño original aunque no haya bytes). Usamos `file.slice().size`,
   * que refleja el tamaño real de los bytes subyacentes (0 para el placeholder de restauración).
   */
  private archivoTieneBytesReales(file: File | null): boolean {
    return !!file && file.slice().size > 0;
  }

  nextStep() {
    if (this.stepOneValid()) {
      this.currentStep.set(1);
    } else {
      this.activeForm.markAllAsTouched();
    }
  }

  prevStep() {
    this.currentStep.set(0);
  }

  viewFile(file: File | null, title: string, documentId?: number | null) {
    if (!file) return;
    if (documentId && !this.archivoTieneBytesReales(file)) {
      const fileUrl = `${environment.apiUrl}/documentos/${documentId}`;
      this.previewUrl.set(this.sanitizer.bypassSecurityTrustResourceUrl(fileUrl));
    } else {
      const fileUrl = URL.createObjectURL(file);
      this.previewUrl.set(this.sanitizer.bypassSecurityTrustResourceUrl(fileUrl));
    }
    this.previewTitle.set(title);
    this.showPreviewModal.set(true);
  }

  closePreviewModal() {
    this.showPreviewModal.set(false);
    this.previewUrl.set(null);
    this.previewTitle.set('');
  }

  onKeyDown(event: KeyboardEvent, action: () => void) {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      action();
    }
  }

  getFile(clave: string): File | null {
    return this.documentosMap()[clave]?.file ?? null;
  }

  getDocumentId(clave: string): number | null {
    return this.documentosMap()[clave]?.id ?? null;
  }

  onFileChange(clave: string, file: File | null) {
    this.documentosMap.update(map => ({
      ...map,
      [clave]: {
        file,
        id: map[clave]?.id ?? null
      }
    }));
  }

  onIdChange(clave: string, id: number | null) {
    this.documentosMap.update(map => ({
      ...map,
      [clave]: {
        file: map[clave]?.file ?? null,
        id
      }
    }));
  }

  onSubmit() {
    this.nombreProyectoTouched.set(true);
    this.municipioTouched.set(true);
    if (!this.activeForm.valid || !this.nombreProyecto().trim() || this.municipioId() === null) {
      this.activeForm.markAllAsTouched();
      return;
    }

    this.saveFlowToStorage();

    this.isSubmitting.set(true);
    this.submitError.set(null);
    this.signError.set(null);

    const docsSummary = this.collectDocsSummary();

    const formValue = { ...this.activeForm.value };
    if (formValue.montoInversion && typeof formValue.montoInversion === 'string') {
      formValue.montoInversion = Number(formValue.montoInversion.replace(/,/g, ''));
    }

    this.solicitudService.generarPdfSolicitud(
      this.personalidadJuridica(),
      formValue as SolicitudFormValue,
      this.nombreProyecto().trim(),
      this.municipioId()!,
      docsSummary,
    ).pipe(
      takeUntilDestroyed(this.destroyRef),
    ).subscribe({
      next: (arrayBuffer) => {
        const bytes = new Uint8Array(arrayBuffer);
        this.docsParaFirmar.set([
          {
            nombre: 'solicitud_autorizacion.pdf',
            bytes,
            clave: 'solicitud_firmada',
          },
        ]);
        this.firmaMetadata.set({
          rfc: this.activeForm.value.rfc ?? '',
          createdAt: new Date().toISOString(),
        });
        this.showFirmaModal.set(true);
        this.isSubmitting.set(false);
      },
      error: (err) => {
        this.isSubmitting.set(false);
        this.submitError.set(extractErrorMessage(err));
      },
    });
  }

  private collectDocsSummary(): { clave: string; documento_id?: number | null; nombre?: string }[] {
    const summary: { clave: string; documento_id?: number | null; nombre?: string }[] = [];

    for (const tipo of this.documentosInversionista()) {
      const entry = this.documentosMap()[tipo.clave];
      if (entry) {
        summary.push({
          clave: tipo.clave,
          documento_id: entry.id,
          nombre: entry.file?.name ?? tipo.nombre,
        });
      }
    }

    for (const tramite of this.tramitesRequisitos()) {
      for (const req of tramite.requisitos) {
        const clave = `tramite_${tramite.id}_doc_${req.id}`;
        const entry = this.tramitesMap()[clave];
        if (entry) {
          summary.push({
            clave,
            documento_id: entry.id,
            nombre: entry.file?.name ?? `${tramite.nombre} - ${req.nombre}`,
          });
        }
      }
    }

    return summary;
  }

  onFirmaFirmado(resultados: ResultadoFirma[]) {
    this.showFirmaModal.set(false);
    this.isSigning.set(true);
    this.signError.set(null);

    const resultado = resultados.find(r => r.clave === 'solicitud_firmada') ?? resultados[0];
    if (!resultado) {
      this.isSigning.set(false);
      this.signError.set('No se obtuvo el resultado de la firma.');
      return;
    }

    const signedFile = new File([new Uint8Array(resultado.signedBytes)], 'solicitud_autorizacion_firmada.pdf', {
      type: 'application/pdf',
    });

    this.documentoService.uploadDocumento(signedFile).pipe(
      takeUntilDestroyed(this.destroyRef),
    ).subscribe({
      next: (uploadRes) => {
        const signedDocId = uploadRes.id;
        const currentDocsMap = {
          ...this.documentosMap(),
          solicitud_firmada: { file: signedFile, id: signedDocId },
        };

        const allowedClaves = [
          ...this.documentosInversionista().map(d => d.clave),
          'solicitud_firmada',
        ];

        const serialsByClave: Record<string, string> = {
          solicitud_firmada: resultado.serial,
        };

        const formValue = { ...this.activeForm.value };
        if (formValue.montoInversion && typeof formValue.montoInversion === 'string') {
          formValue.montoInversion = Number(formValue.montoInversion.replace(/,/g, ''));
        }

        const tramiteIds = this.tramitesRequisitos().map(t => t.id);

        const tramiteDocsPayload: { clave: string; documento_id: number; tramite_requisito_id?: number }[] = [];
        for (const tramite of this.tramitesRequisitos()) {
          for (const req of tramite.requisitos) {
            const clave = `tramite_${tramite.id}_doc_${req.id}`;
            const entry = this.tramitesMap()[clave];
            if (entry?.id) {
              tramiteDocsPayload.push({
                clave,
                documento_id: entry.id,
                tramite_requisito_id: req.id,
              });
            }
          }
        }

        this.solicitudService.enviarSolicitud(
          this.personalidadJuridica(),
          formValue as SolicitudFormValue,
          this.nombreProyecto().trim() || null,
          currentDocsMap,
          allowedClaves,
          serialsByClave,
          this.municipioId(),
          tramiteIds,
          tramiteDocsPayload,
        ).pipe(
          takeUntilDestroyed(this.destroyRef),
        ).subscribe({
          next: (result) => {
            this.isSigning.set(false);
            this.submitFolio.set(result.folio);
            this.submitId.set(result.id);
            this.submitSuccess.set(true);
            this.clearUploadedDocumentsCache();
            localStorage.removeItem(STORAGE_KEY);
          },
          error: (err) => {
            this.isSigning.set(false);
            this.submitError.set(extractErrorMessage(err));
          },
        });
      },
      error: (err) => {
        this.isSigning.set(false);
        this.signError.set(extractErrorMessage(err));
      },
    });
  }

  onFirmaCerrado() {
    this.showFirmaModal.set(false);
    this.docsParaFirmar.set([]);
    this.isSubmitting.set(false);
    this.submitError.set(null);
  }

  clearUploadedDocumentsCache() {
    const keysToRemove: string[] = [];
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key && key.startsWith('doc_upload_')) {
        keysToRemove.push(key);
      }
    }
    keysToRemove.forEach(key => localStorage.removeItem(key));
  }

  descargarAcuse() {
    const id = this.submitId();
    if (!id) return;
    window.location.href = `${environment.apiUrl}/solicitudes/${id}/acuse`;
  }

  goBack() {
    this.router.navigate(['/inversores/autorizaciones']);
  }
}
